  def cycle_frame_Id : Art.PortId
  def image_frame_Id : Art.PortId
  def collection_proposal_Id : Art.PortId
  def release_proposal_Id : Art.PortId
  def decision_frame_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var decision_frame: EIT_Acquisition_Supervisor.DecisionFrame = $

  def put_decision_frame(value : EIT_Acquisition_Supervisor.DecisionFrame) : Unit = {
    Contract(
      Modifies(decision_frame),
      Ensures(
        decision_frame == value
      )
    )
    Spec {
      decision_frame = value
    }

    Art.putValue(decision_frame_Id, EIT_Acquisition_Supervisor.DecisionFrame_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

